// === Tab: mySketch ===
let n = 2000;
let a = [];
let lastLightningTime = 0;
let pg;
let thunder;
let rain;

function preload() {
  thunder = loadSound('https://openprocessing.org/sketch/2746218/files/thunder.mp3');
	rain = loadSound('https://openprocessing.org/sketch/2746218/files/rain.mp3');
}

function setup() {
	createCanvas(800, 800);
	pg = createGraphics(800, 800);
	pg.fill(40);
	for (let i = 0; i < 30; i++) pg.rect(random(-100, width), height / 2, random(50, 200), -random(10, 180));
	for (let i = 0; i < n * 2; i++) a[i] = random(width);
	background(0);
	noStroke();
	rain.play();
}

function draw() {
	let isLightning = false;
	if (random(200) < 1 || millis() - lastLightningTime > 3000) {
		thunder.play();
		fill('#ff0');
		lastLightningTime = millis();
		isLightning = true;
	} else {
		fill(0, 20);
	}
	square(0, 0, width);

	if (isLightning) {
		image(pg, 0, 0);
		fill(0, 150);
		rect(0, height / 2, width, height / 2);
	}

	fill(255, 99);
	for (let i = 0; i < n; i++) {
		circle(a[i], a[i + n], 2);
		a[i + n] += (0.1 + noise(i) * 0.7) * 15;
		if (a[i + n] > height) {
			a[i + n] = 0;
			a[i] = random(width);
		}
	}
}

